/**
 * Targets wave 5 (September 2026, docs/CONTENT-ROADMAP.md): the gene and receptor symbols that two or more drug
 * records name in their mechanism or summary text but that had no target page (measured by `npm run content:gaps`).
 *
 * Sources, and nothing else: identifiers, approved names, aliases and loci from the HGNC REST API
 * (rest.genenames.org/fetch/symbol/<SYMBOL>, read 22 September 2026); the protein's function paraphrased from the
 * UniProt REST API function comment for the accession HGNC lists (rest.uniprot.org/uniprotkb/<ACC>.json); the role in
 * cancer treatment from the OnCo drug and pathway records that name the symbol (listed in `drugs` where the drug acts
 * on the protein, in `related` where the protein is a biomarker, a downstream node or a released partner). No
 * prevalence rows: neither registry gives a positivity rate, so the target-prevalence gauge lists these until a
 * sourced figure is added. Cancers are those of the linked drug records.
 *
 * Folded into existing records rather than written: PRC2 (alias on ezh2), BET (alias on brd4 below), BH3 (alias on
 * bim below). "LAR" in the drug texts is octreotide LAR (long-acting release), not a target, and is now a stop word
 * in scripts/content-gaps.ts. Registered in src/data/index.ts as `targetsWaveSoc`; cross-references appended to
 * src/data/target-xrefs.ts from the same HGNC responses; the file is listed in scripts/enrich-target-ids.ts.
 */
import type { TargetInput } from "@/lib/schema";

const asOf = "2026-09-22";
const HGNC = (id: string) => `https://www.genenames.org/data/gene-symbol-report/#!/hgnc_id/${id}`;
const UNIPROT = (acc: string) => `https://www.uniprot.org/uniprotkb/${acc}/entry`;
const GENE = (id: string) => `https://www.ncbi.nlm.nih.gov/gene/${id}`;
const provenance = { editedBy: "OnCo content wave 5 (HGNC REST, UniProt REST, corpus drug and pathway records)", editedOn: asOf };
const tags = ["wave5-target"];
const NO_PREVALENCE = "Prevalence not recorded in this wave: HGNC and UniProt carry no positivity rates and no other source was consulted.";

type T = Omit<TargetInput, "kind" | "asOf" | "provenance" | "tags">;
const t = (x: T): TargetInput => ({
  kind: "target", asOf, provenance, tags,
  ...x,
  links: [
    ...(x.hgnc ? [{ label: `HGNC ${x.hgnc}`, url: HGNC(x.hgnc) }] : []),
    ...(x.uniprot ? [{ label: `UniProt ${x.uniprot}`, url: UNIPROT(x.uniprot) }] : []),
    ...(x.entrez ? [{ label: `NCBI Gene ${x.entrez}`, url: GENE(x.entrez) }] : []),
    ...(x.links ?? []),
  ],
  notes: [NO_PREVALENCE, ...(x.notes ?? [])],
});

